import { useMemo, useState } from 'react';
import { Badge, Pagination, Table } from '@jinx-ui/react';

// Assumes Jinx UI compound Table, Badge `tone`, and controlled Pagination — adjust names if the installed version differs.

export type User = {
  id: string | number;
  name: string;
  role: string;
  active: boolean;
};

type UsersTableProps = {
  users: User[];
};

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
      }}
    >
      <Table>
        <Table.Header>
          <Table.Row>
            <Table.HeaderCell>Имя</Table.HeaderCell>
            <Table.HeaderCell>Роль</Table.HeaderCell>
            <Table.HeaderCell>Статус</Table.HeaderCell>
          </Table.Row>
        </Table.Header>
        <Table.Body>
          {rows.map((user) => (
            <Table.Row key={user.id}>
              <Table.Cell>{user.name}</Table.Cell>
              <Table.Cell>{user.role}</Table.Cell>
              <Table.Cell>
                <Badge tone={user.active ? 'success' : 'neutral'}>
                  {user.active ? 'Активен' : 'Отключён'}
                </Badge>
              </Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table>

      <Pagination page={currentPage} pageCount={pageCount} onChange={setPage} />
    </div>
  );
}

